function routeFor(pathname) {
  const normalized = pathname.replace(/\/$/, '') || '/';
  if (normalized === '/') return { name: 'home' };
  if (normalized === '/services') return { name: 'services' };
  if (normalized.startsWith('/services/')) return { name: 'service', id: normalized.slice('/services/'.length) };
  if (normalized === '/pricing') return { name: 'pricing' };
  if (normalized === '/cases') return { name: 'cases' };
  if (normalized === '/approach') return { name: 'approach' };
  if (normalized === '/about') return { name: 'about' };
  if (normalized === '/contact') return { name: 'contact' };
  if (normalized === '/privacy') return { name: 'privacy' };
  return { name: '404' };
}

function useRoute() {
  const [route, setRoute] = useState(() => routeFor(window.location.pathname));
  useEffect(() => {
    const onPop = () => setRoute(routeFor(window.location.pathname));
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);
  const navigate = (to) => {
    const [path, hash] = to.split('#');
    window.history.pushState({}, '', `${path}${hash ? `#${hash}` : ''}`);
    setRoute(routeFor(path));
    window.scrollTo({ top: 0, behavior: 'auto' });
  };
  return [route, navigate];
}

function ParticleField() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    let frame;
    let width = 0;
    let height = 0;
    const points = Array.from({ length: 38 }, (_, index) => ({ x: (index * 97) % 1000, y: (index * 53) % 480, vx: (index % 3 - 1) * 0.08, vy: (index % 4 - 2) * 0.04 }));
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const resize = () => { width = canvas.width = canvas.offsetWidth * window.devicePixelRatio; height = canvas.height = canvas.offsetHeight * window.devicePixelRatio; context.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0); width /= window.devicePixelRatio; height /= window.devicePixelRatio; };
    const draw = () => {
      context.clearRect(0, 0, width, height);
      points.forEach((point) => { point.x += reduced ? 0 : point.vx; point.y += reduced ? 0 : point.vy; if (point.x < 0 || point.x > width) point.vx *= -1; if (point.y < 0 || point.y > height) point.vy *= -1; });
      points.forEach((point, index) => points.slice(index + 1).forEach((other) => { const dx = point.x - other.x; const dy = point.y - other.y; const distance = Math.sqrt(dx * dx + dy * dy); if (distance < 145) { context.strokeStyle = `rgba(1, 97, 254, ${0.08 * (1 - distance / 145)})`; context.lineWidth = 1; context.beginPath(); context.moveTo(point.x, point.y); context.lineTo(other.x, other.y); context.stroke(); } }));
      points.forEach((point) => { context.fillStyle = 'rgba(1, 97, 254, .22)'; context.beginPath(); context.arc(point.x, point.y, 1.7, 0, Math.PI * 2); context.fill(); });
      if (!reduced) frame = requestAnimationFrame(draw);
    };
    resize(); draw(); window.addEventListener('resize', resize);
    return () => { cancelAnimationFrame(frame); window.removeEventListener('resize', resize); };
  }, []);
  return <canvas className="particle-field" ref={canvasRef} aria-hidden="true" />;
}

function Header({ t, lang, setLang, navigate, route }) {
  const [open, setOpen] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  useEffect(() => {
    if (!mobileOpen) return undefined;
    const closeOnEscape = (event) => { if (event.key === 'Escape') setMobileOpen(false); };
    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', closeOnEscape);
    return () => { document.body.style.overflow = ''; window.removeEventListener('keydown', closeOnEscape); };
  }, [mobileOpen]);
  const go = (to) => { setOpen(false); setMobileOpen(false); navigate(to); };
  const isActive = (name) => route.name === name || (name === 'services' && route.name === 'service');
  return <>
    <header className="site-header">
      <div className="header-inner">
        <button className="brand" type="button" onClick={() => go('/')} aria-label="WINFO home"><img src="/WINFO-blue.png" alt="WINFO" /><span>{t.brand}</span></button>
        <nav className="desktop-nav" aria-label="Primary navigation">
          <div className="nav-menu-shell" onMouseEnter={() => setOpen(true)} onMouseLeave={() => setOpen(false)} onFocus={() => setOpen(true)} onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false); }}>
            <button type="button" className={`nav-link nav-services ${open ? 'is-open' : ''} ${isActive('services') ? 'is-active' : ''}`} aria-expanded={open} aria-controls="services-mega-menu" aria-current={isActive('services') ? 'page' : undefined} onClick={() => go('/services')}>{t.nav.services}<Icon name="chevron" size={15} /></button>
            <div id="services-mega-menu" className={`mega-menu ${open ? 'is-open' : ''}`}>
              <div className="mega-grid"><div><span className="menu-label">{t.menu.start}</span>{serviceItems.filter((item) => item.group === 'start').map((item) => <ServiceMenuLink key={item.id} item={item} t={t} lang={lang} go={go} />)}</div><div><span className="menu-label">{t.menu.compliance}</span>{serviceItems.filter((item) => item.group === 'compliance').map((item) => <ServiceMenuLink key={item.id} item={item} t={t} lang={lang} go={go} />)}</div><div><span className="menu-label">{t.menu.grow}</span>{serviceItems.filter((item) => item.group === 'grow').map((item) => <ServiceMenuLink key={item.id} item={item} t={t} lang={lang} go={go} />)}</div><div className="mega-aside"><span>{t.menu.support}</span><button type="button" onClick={() => go('/contact')}>{t.menu.talk}<Icon name="arrow" size={16} /></button></div></div>
              <div className="mega-footer"><button type="button" onClick={() => go('/services')}>{t.menu.explore}<Icon name="arrow" size={16} /></button><span>WINFO / 01</span></div>
            </div>
          </div>
          <button type="button" aria-current={isActive('pricing') ? 'page' : undefined} className={`nav-link ${isActive('pricing') ? 'is-active' : ''}`} onClick={() => go('/pricing')}>{t.nav.pricing}</button><button type="button" aria-current={isActive('cases') ? 'page' : undefined} className={`nav-link ${isActive('cases') ? 'is-active' : ''}`} onClick={() => go('/cases')}>{t.nav.cases}</button><button type="button" aria-current={isActive('approach') ? 'page' : undefined} className={`nav-link ${isActive('approach') ? 'is-active' : ''}`} onClick={() => go('/approach')}>{t.nav.approach}</button><button type="button" aria-current={isActive('about') ? 'page' : undefined} className={`nav-link ${isActive('about') ? 'is-active' : ''}`} onClick={() => go('/about')}>{t.nav.about}</button><button type="button" aria-current={isActive('contact') ? 'page' : undefined} className={`nav-link ${isActive('contact') ? 'is-active' : ''}`} onClick={() => go('/contact')}>{t.nav.contact}</button>
        </nav>
        <div className="header-actions"><div className="language-switcher" aria-label="Language switcher">{languages.map((item) => <button key={item.code} type="button" className={lang === item.code ? 'is-active' : ''} onClick={() => setLang(item.code)}>{item.label}</button>)}</div><button type="button" className="header-cta" onClick={() => go('/contact')}>{t.nav.cta}<Icon name="arrow" size={16} /></button><button type="button" className="mobile-toggle" onClick={() => setMobileOpen(true)} aria-label={t.nav.menu} aria-expanded={mobileOpen}><Icon name="menu" size={22} /></button></div>
      </div>
    </header>
    {mobileOpen && <div className="mobile-menu" role="dialog" aria-modal="true" aria-label={t.nav.menu}><div className="mobile-menu-head"><button className="brand" type="button" onClick={() => go('/')}><img src="/WINFO-blue.png" alt="WINFO" /><span>{t.brand}</span></button><button type="button" className="mobile-close" onClick={() => setMobileOpen(false)} aria-label={t.nav.close}><Icon name="close" size={22} /></button></div><div className="mobile-menu-scroll"><button type="button" className="mobile-nav-link" onClick={() => go('/services')}>{t.nav.services}<Icon name="arrow" size={17} /></button>{serviceItems.map((item) => <button type="button" className="mobile-service-link" key={item.id} onClick={() => go(`/services/${item.id}`)}><Icon name={item.icon} size={18} /><span>{serviceContent[item.key][lang].name}</span><Icon name="arrow" size={15} /></button>)}<button type="button" className="mobile-nav-link" onClick={() => go('/pricing')}>{t.nav.pricing}<Icon name="arrow" size={17} /></button><button type="button" className="mobile-nav-link" onClick={() => go('/cases')}>{t.nav.cases}<Icon name="arrow" size={17} /></button><button type="button" className="mobile-nav-link" onClick={() => go('/approach')}>{t.nav.approach}<Icon name="arrow" size={17} /></button><button type="button" className="mobile-nav-link" onClick={() => go('/about')}>{t.nav.about}<Icon name="arrow" size={17} /></button><button type="button" className="mobile-nav-link" onClick={() => go('/contact')}>{t.nav.contact}<Icon name="arrow" size={17} /></button></div><div className="mobile-menu-footer"><div className="language-switcher">{languages.map((item) => <button key={item.code} type="button" className={lang === item.code ? 'is-active' : ''} onClick={() => setLang(item.code)}>{item.label}</button>)}</div><button type="button" className="header-cta" onClick={() => go('/contact')}>{t.nav.cta}<Icon name="arrow" size={16} /></button></div></div>}
  </>;
}

function ServiceMenuLink({ item, t, lang, go }) { const title = serviceContent[item.key][lang].name; return <button type="button" className="mega-service-link" onClick={() => go(`/services/${item.id}`)}><span className="menu-icon"><Icon name={item.icon} size={18} /></span><span><strong>{title}</strong><small>{item.group === 'start' ? t.menu.start : item.group === 'grow' ? t.menu.grow : t.menu.compliance}</small></span><Icon name="arrow" size={15} /></button>; }

function ServiceCard({ item, lang, t, navigate }) { const service = serviceContent[item.key][lang]; return <button type="button" className="service-card" onClick={() => navigate(`/services/${item.id}`)}><span className="service-card-top"><span className="service-icon"><Icon name={item.icon} size={22} /></span><span className="service-index">0{serviceItems.indexOf(item) + 1}</span></span><span className="service-card-title">{service.name}</span><span className="service-card-body">{service.summary}</span><span className="service-card-link">{t.services.path}<Icon name="arrow" size={15} /></span></button>; }

function PageCta({ t, navigate }) { return <section className="section final-cta page-cta"><div className="content-width final-cta-inner"><div><div className="eyebrow"><span className="eyebrow-dot" />{t.nav.contact}</div><h2>{t.home.finalTitle}</h2><p>{t.home.finalBody}</p></div><button type="button" className="button button-primary" onClick={() => navigate('/contact')}>{t.home.finalButton}<Icon name="arrow" size={17} /></button></div></section>; }

function TestimonialSection({ lang, page }) { const labels = testimonialCopy[lang] || testimonialCopy.en; const item = labels.items[page] || labels.items.home; return <section className="section testimonial-section"><div className="content-width testimonial-layout"><div><div className="eyebrow"><span className="eyebrow-dot" />{labels.kicker}</div><h2>{labels.title}</h2><blockquote>“{item.quote}”</blockquote><cite>{item.by}</cite></div><div className="testimonial-proof"><span className="rating-stars" aria-hidden="true">★★★★★</span><strong>4.6 <small>/ 5</small></strong><span>{labels.ratingLabel}</span><p>{labels.note}</p></div></div></section>; }

function ServiceFinder({ lang, navigate }) { const [selectedId, setSelectedId] = useState('company-setup'); const [step, setStep] = useState(1); const labels = finderCopy[lang]; const selectedOption = finderOptions.find((option) => option.id === selectedId) || finderOptions[0]; const selectedItem = serviceItems.find((item) => item.id === selectedOption.id); const selectedService = serviceContent[selectedItem.key][lang]; return <section className="section service-finder-section"><div className="content-width service-finder"><div className="finder-heading"><div className="eyebrow"><span className="eyebrow-dot" />WINFO / FIND YOUR STARTING POINT</div><h2>{labels.title}</h2><p>{labels.body}</p><div className="finder-progress" aria-label={`${step} of 2`}><span className={step === 1 ? 'is-active' : 'is-complete'}>01</span><i className={step === 2 ? 'is-active' : ''} /><span className={step === 2 ? 'is-active' : ''}>02</span></div></div><div className={`finder-content finder-step-${step}`}><div className="finder-panel-heading"><span>{step === 1 ? '01 / 02' : '02 / 02'}</span><strong>{step === 1 ? labels.stepOne : labels.stepTwo}</strong></div>{step === 1 ? <div className="finder-options">{labels.options.map((label, index) => { const isSelected = selectedId === finderOptions[index].id; return <button type="button" key={label} className={isSelected ? 'is-active' : ''} aria-pressed={isSelected} onClick={() => { setSelectedId(finderOptions[index].id); setStep(2); }}><span>0{index + 1}</span><strong>{label}</strong><Icon name="arrow" size={16} /></button>; })}</div> : <div className="finder-result"><span>{labels.result}</span><h3>{selectedService.name}</h3><p>{selectedService.summary}</p><div className="finder-result-actions"><button type="button" className="button button-primary" onClick={() => navigate(`/services/${selectedItem.id}`)}>{labels.cta}<Icon name="arrow" size={16} /></button><button type="button" className="text-button" onClick={() => setStep(1)}>{labels.back}<Icon name="arrow" size={16} /></button></div></div>}</div></div></section>; }

function FAQSection({ lang, context }) { const labels = faqCopy[lang][context]; const [openIndex, setOpenIndex] = useState(0); return <section className="section faq-section"><div className="content-width faq-layout"><div className="faq-heading"><div className="eyebrow"><span className="eyebrow-dot" />{labels.kicker}</div><h2>{labels.title}</h2></div><div className="faq-list">{labels.items.map((item, index) => { const isOpen = openIndex === index; const answerId = `faq-answer-${context}-${index}`; return <div className={`faq-item ${isOpen ? 'is-open' : ''}`} key={item.q}><button type="button" className="faq-trigger" aria-expanded={isOpen} aria-controls={answerId} onClick={() => setOpenIndex(isOpen ? -1 : index)}><span>{item.q}</span><span className="faq-plus" aria-hidden="true">{isOpen ? '−' : '+'}</span></button><div id={answerId} className="faq-answer" hidden={!isOpen}><p>{item.a}</p></div></div>; })}</div></div></section>; }

function HomePage({ t, lang, navigate }) { return <main>
  <section className="hero-section"><ParticleField /><div className="hero-inner"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot" />WINFO / BUSINESS SOLUTIONS</div><h1>{t.hero.title}</h1><p>{t.hero.body}</p><div className="hero-actions"><button type="button" className="button button-primary" onClick={() => navigate('/contact')}>{t.hero.primary}<Icon name="arrow" size={17} /></button><button type="button" className="text-button" onClick={() => navigate('/services')}>{t.hero.secondary}<Icon name="arrow" size={17} /></button></div><span className="hero-note">{t.hero.note}</span></div><div className="hero-visual"><div className="hero-image-wrap"><img src="/Main_banner.jpg" alt="Hong Kong skyline at night" /><div className="hero-image-shade" /></div><div className="hero-info-card"><span>{t.hero.visualLabel}</span><strong>{t.hero.visualTitle}</strong><p>{t.hero.visualText}</p><button type="button" onClick={() => navigate('/approach')}>{t.nav.approach}<Icon name="arrow" size={15} /></button></div><div className="hero-coordinate">22.3193° N<br />114.1694° E</div></div></div><div className="hero-bottom"><span>01 / 05</span><div className="hero-rule"><i /></div><span>Hong Kong · Cross-border</span></div></section>
  <section className="proof-strip"><div className="content-width proof-inner"><span className="proof-label">WINFO SUPPORTS</span>{t.proof.map((item) => <span key={item} className="proof-item"><i /><span>{item}</span></span>)}</div></section>
  <section className="section services-preview"><div className="content-width"><div className="section-heading split-heading"><div><div className="eyebrow"><span className="eyebrow-dot" />{t.home.servicesKicker}</div><h2>{t.home.servicesTitle}</h2></div><div className="heading-side"><p>{t.home.servicesBody}</p><button type="button" className="text-button" onClick={() => navigate('/services')}>{t.home.viewAll}<Icon name="arrow" size={17} /></button></div></div><div className="service-grid">{serviceItems.slice(0, 4).map((item) => <ServiceCard key={item.id} item={item} lang={lang} t={t} navigate={navigate} />)}</div></div></section>
  <ServiceFinder lang={lang} navigate={navigate} />
  <section className="section blue-band"><div className="content-width blue-band-grid"><div><div className="eyebrow eyebrow-light"><span className="eyebrow-dot" />{t.home.whyKicker}</div><h2>{t.home.whyTitle}</h2></div><div><p>{t.home.whyBody}</p><ul className="check-list">{t.home.principles.map((item) => <li key={item}><Icon name="check" size={17} />{item}</li>)}</ul><button type="button" className="button button-white" onClick={() => navigate('/approach')}>{t.nav.approach}<Icon name="arrow" size={17} /></button></div></div></section>
  <section className="section cases-preview"><div className="content-width"><div className="section-heading split-heading"><div><div className="eyebrow"><span className="eyebrow-dot" />{t.home.casesKicker}</div><h2>{t.home.casesTitle}</h2></div><div className="heading-side"><p>{t.home.casesBody}</p><button type="button" className="text-button" onClick={() => navigate('/cases')}>{t.home.casesButton}<Icon name="arrow" size={17} /></button></div></div><div className="case-feature"><div className="case-feature-number">01</div><div><span className="case-kicker">WINFO / OPERATING CLARITY</span><h3>Make the next business decision easier to own.</h3><p>{t.home.quote}</p><span className="case-by">{t.home.quoteBy}</span></div><div className="case-feature-mark"><span>→</span><small>EXPLORE<br />THE METHOD</small></div></div></div></section>
  <TestimonialSection lang={lang} page="home" />
  <section className="section final-cta"><div className="content-width final-cta-inner"><div><div className="eyebrow"><span className="eyebrow-dot" />WINFO / NEXT STEP</div><h2>{t.home.finalTitle}</h2><p>{t.home.finalBody}</p></div><button type="button" className="button button-primary" onClick={() => navigate('/contact')}>{t.home.finalButton}<Icon name="arrow" size={17} /></button></div></section>
 </main>; }

function ServicesPage({ t, lang, navigate }) { return <PageShell className="services-page"><PageIntro kicker={t.services.kicker} title={t.services.title} body={t.services.body} /><section className="content-width featured-service"><div className="featured-service-copy"><span className="eyebrow"><span className="eyebrow-dot" />{t.services.featured}</span><h2>{t.services.iangTitle}</h2><p>{t.services.iangBody}</p><button type="button" className="button button-primary" onClick={() => navigate('/services/iang')}>{t.services.path}<Icon name="arrow" size={17} /></button></div><div className="featured-service-art"><ParticleField /><div className="art-code">HKG<br />IANG<br />01</div><div className="art-orbit" /></div></section><section className="section services-all"><div className="content-width"><div className="eyebrow"><span className="eyebrow-dot" />{t.services.all}</div><div className="service-grid service-grid-six">{serviceItems.map((item) => <ServiceCard key={item.id} item={item} lang={lang} t={t} navigate={navigate} />)}</div></div></section><TestimonialSection lang={lang} page="services" /><PageCta t={t} navigate={navigate} /></PageShell>; }

function PageShell({ children, className = '' }) { return <main className={className}>{children}</main>; }
function PageIntro({ kicker, title, body }) { return <section className="page-intro"><div className="content-width page-intro-inner"><div className="eyebrow"><span className="eyebrow-dot" />{kicker}</div><h1>{title}</h1><p>{body}</p></div></section>; }

function ServicePage({ t, lang, id, navigate }) { const item = serviceItems.find((service) => service.id === id); const content = item ? serviceContent[item.key][lang] : null; if (!content) return <NotFoundPage t={t} navigate={navigate} />; return <PageShell className="service-detail-page"><section className="page-intro service-detail-intro"><div className="content-width"><button type="button" className="back-link" onClick={() => navigate('/services')}><span>←</span>{t.servicePage.back}</button><div className="service-detail-layout"><div><div className="service-icon large"><Icon name={item.icon} size={28} /></div><div className="eyebrow"><span className="eyebrow-dot" />{t.servicePage.overview}</div><h1>{content.name}</h1><p>{content.summary}</p></div><div className="detail-note"><span>WINFO / {String(serviceItems.indexOf(item) + 1).padStart(2, '0')}</span><p>{content.detail}</p></div></div></div></section><section className="section detail-content"><div className="content-width detail-grid"><div><div className="eyebrow"><span className="eyebrow-dot" />{t.servicePage.included}</div><ul className="included-list">{content.items.map((entry) => <li key={entry}><Icon name="check" size={18} /><span>{entry}</span></li>)}</ul></div><div><div className="eyebrow"><span className="eyebrow-dot" />{t.servicePage.process}</div><div className="process-list">{content.process.map((entry, index) => <div className="process-row" key={entry}><span>{String(index + 1).padStart(2, '0')}</span><strong>{entry}</strong></div>)}</div></div></div></section><section className="section detail-placeholder"><div className="content-width placeholder-box"><span className="placeholder-line" /><p>{t.servicePage.placeholder}</p><span className="placeholder-line short" /></div></section><FAQSection lang={lang} context="service" /><TestimonialSection lang={lang} page={id} /><section className="section detail-cta"><div className="content-width detail-cta-inner"><div><h2>{t.servicePage.ready}</h2><p>{t.servicePage.readyBody}</p></div><button type="button" className="button button-primary" onClick={() => navigate('/contact')}>{t.servicePage.enquire}<Icon name="arrow" size={17} /></button></div></section></PageShell>; }

function PricingPage({ t, lang, navigate }) { return <PageShell className="pricing-page"><PageIntro kicker={t.pricing.kicker} title={t.pricing.title} body={t.pricing.body} /><section className="section pricing-section"><div className="content-width"><div className="pricing-grid">{t.pricing.plans.map((plan) => <div className={`pricing-plan ${plan.featured ? 'is-featured' : ''}`} key={plan.name}>{plan.featured && <span className="featured-label">RECOMMENDED</span>}<span className="plan-index">0{t.pricing.plans.indexOf(plan) + 1}</span><h2>{plan.name}</h2><p>{plan.desc}</p><ul className="check-list dark">{plan.items.map((item) => <li key={item}><Icon name="check" size={16} />{item}</li>)}</ul><button type="button" className={plan.featured ? 'button button-primary' : 'text-button'} onClick={() => navigate('/contact')}>{plan.action}<Icon name="arrow" size={16} /></button></div>)}</div><p className="pricing-note">{t.pricing.note}</p></div></section><FAQSection lang={lang} context="pricing" /><TestimonialSection lang={lang} page="pricing" /></PageShell>; }

function CasesPage({ t, lang, navigate }) { const [filterIndex, setFilterIndex] = useState(0); const activeFilter = t.cases.filters[filterIndex] || t.cases.filters[0]; const projects = filterIndex === 0 ? t.cases.projects : t.cases.projects.filter((item) => item.type === activeFilter); return <PageShell className="cases-page"><PageIntro kicker={t.cases.kicker} title={t.cases.title} body={t.cases.body} /><section className="section cases-section"><div className="content-width"><div className="filter-row" role="tablist" aria-label={t.cases.kicker}>{t.cases.filters.map((item, index) => <button type="button" role="tab" aria-selected={filterIndex === index} className={filterIndex === index ? 'is-active' : ''} key={item} onClick={() => setFilterIndex(index)}>{item}</button>)}</div><div className="case-list" aria-live="polite">{projects.map((project, index) => <article className="case-row" key={project.title}><span className="case-row-number">{String(index + 1).padStart(2, '0')}</span><div><span className="case-kicker">{project.type}</span><h2>{project.title}</h2><p>{project.body}</p></div><div className="case-result"><span>RESULT</span><strong>{project.result}</strong></div></article>)}</div></div></section><TestimonialSection lang={lang} page="cases" /><PageCta t={t} navigate={navigate} /></PageShell>; }

function ApproachPage({ t, lang, navigate }) { return <PageShell className="approach-page"><PageIntro kicker={t.approach.kicker} title={t.approach.title} body={t.approach.body} /><section className="section approach-section"><div className="content-width approach-list">{t.approach.steps.map((step) => <article className="approach-step" key={step.n}><span className="step-number">{step.n}</span><div><h2>{step.title}</h2><p>{step.body}</p></div><span className="step-arrow">↘</span></article>)}</div></section><TestimonialSection lang={lang} page="approach" /><PageCta t={t} navigate={navigate} /></PageShell>; }

function AboutPage({ t, lang, navigate }) { return <PageShell className="about-page"><PageIntro kicker={t.about.kicker} title={t.about.title} body={t.about.body} /><section className="section about-stats"><div className="content-width stats-grid">{t.about.stats.map((stat) => <div className="stat" key={stat.label}><strong>{stat.value}</strong><span>{stat.label}</span></div>)}</div></section><section className="section values-section"><div className="content-width values-grid"><div><div className="eyebrow"><span className="eyebrow-dot" />WINFO / VALUES</div><h2>{t.about.valuesTitle}</h2></div><ul className="number-list">{t.about.values.map((value, index) => <li key={value}><span>0{index + 1}</span><p>{value}</p></li>)}</ul></div></section><TestimonialSection lang={lang} page="about" /><PageCta t={t} navigate={navigate} /></PageShell>; }

function ContactPage({ t, lang }) { const [sent, setSent] = useState(false); const [form, setForm] = useState({ name: '', email: '', company: '', message: '' }); const update = (key, value) => setForm((current) => ({ ...current, [key]: value })); return <PageShell className="contact-page"><PageIntro kicker={t.contact.kicker} title={t.contact.title} body={t.contact.body} /><section className="section contact-section"><div className="content-width contact-grid"><div className="contact-details"><span className="eyebrow"><span className="eyebrow-dot" />{t.contact.detailsTitle}</span><a href={`mailto:${t.contact.email}`}><Icon name="mail" size={18} />{t.contact.email}</a><a href={`tel:${t.contact.phone.replace(/\s/g, '')}`}><Icon name="phone" size={18} />{t.contact.phone}</a><p><Icon name="map" size={18} />{t.contact.address}</p><span className="hours">{t.contact.hours}</span></div><form className="contact-form" onSubmit={(event) => { event.preventDefault(); setSent(true); }}><label>{t.contact.form.name}<input required value={form.name} onChange={(event) => update('name', event.target.value)} placeholder={t.contact.form.name} /></label><label>{t.contact.form.email}<input required type="email" value={form.email} onChange={(event) => update('email', event.target.value)} placeholder={t.contact.form.email} /></label><label>{t.contact.form.company}<input value={form.company} onChange={(event) => update('company', event.target.value)} placeholder={t.contact.form.company} /></label><label>{t.contact.form.message}<textarea required value={form.message} onChange={(event) => update('message', event.target.value)} placeholder={t.contact.form.message} rows="5" /></label><button type="submit" className="button button-primary">{sent ? t.contact.form.success : t.contact.form.send}<Icon name={sent ? 'check' : 'arrow'} size={17} /></button></form></div></section><TestimonialSection lang={lang} page="contact" /></PageShell>; }

function PrivacyPage({ t }) { return <PageShell className="privacy-page"><PageIntro kicker={t.privacy.kicker} title={t.privacy.title} body={t.privacy.intro} /><section className="section privacy-section"><div className="content-width privacy-layout"><aside><span>{t.privacy.updated}</span><a href="mailto:enquiry@winfo.hk">enquiry@winfo.hk</a></aside><div className="privacy-copy">{t.privacy.sections.map((section) => <section key={section.title}><h2>{section.title}</h2><p>{section.body}</p></section>)}</div></div></section></PageShell>; }
function NotFoundPage({ t, navigate }) { return <PageShell className="not-found-page"><section className="page-intro"><div className="content-width not-found"><div className="eyebrow"><span className="eyebrow-dot" />{t.notFound.kicker}</div><h1>{t.notFound.title}</h1><p>{t.notFound.body}</p><div className="hero-actions"><button type="button" className="button button-primary" onClick={() => navigate('/')}>{t.notFound.home}<Icon name="arrow" size={17} /></button><button type="button" className="text-button" onClick={() => navigate('/contact')}>{t.notFound.contact}<Icon name="arrow" size={17} /></button></div></div></section></PageShell>; }

function Footer({ t, navigate }) { return <footer className="site-footer"><div className="content-width footer-main"><div className="footer-brand"><button className="brand" type="button" onClick={() => navigate('/')}><img src="/WINFO-blue.png" alt="WINFO" /><span>{t.brand}</span></button><p>{t.footer.line}</p></div><div className="footer-columns"><div><span>{t.footer.services}</span><button type="button" onClick={() => navigate('/services')}>{t.nav.services}</button><button type="button" onClick={() => navigate('/pricing')}>{t.nav.pricing}</button><button type="button" onClick={() => navigate('/cases')}>{t.nav.cases}</button></div><div><span>{t.footer.company}</span><button type="button" onClick={() => navigate('/about')}>{t.nav.about}</button><button type="button" onClick={() => navigate('/approach')}>{t.nav.approach}</button><button type="button" onClick={() => navigate('/contact')}>{t.nav.contact}</button></div><div><span>{t.footer.legal}</span><button type="button" onClick={() => navigate('/privacy')}>{t.footer.privacy}</button><a href="mailto:enquiry@winfo.hk">enquiry@winfo.hk</a><a href="tel:+85266515286">+852 6651 5286</a></div></div></div><div className="content-width footer-bottom"><span>© {new Date().getFullYear()} {t.footer.copyright}</span><span>HONG KONG / WINFO</span></div></footer>; }

function App() { const [route, navigate] = useRoute(); const [lang, setLang] = useState(() => window.localStorage.getItem('winfo-language') || 'en'); const t = useMemo(() => copy[lang] || copy.en, [lang]); useEffect(() => { window.localStorage.setItem('winfo-language', lang); document.documentElement.lang = lang === 'en' ? 'en' : lang === 'zh-TW' ? 'zh-Hant' : 'zh-Hans'; document.title = route.name === 'home' ? 'WINFO | Business Solutions in Hong Kong' : `${route.name === '404' ? 'Page not found' : route.name[0].toUpperCase() + route.name.slice(1)} | WINFO`; }, [lang, route]); let content; if (route.name === 'home') content = <HomePage t={t} lang={lang} navigate={navigate} />; else if (route.name === 'services') content = <ServicesPage t={t} lang={lang} navigate={navigate} />; else if (route.name === 'service') content = <ServicePage t={t} lang={lang} id={route.id} navigate={navigate} />; else if (route.name === 'pricing') content = <PricingPage t={t} lang={lang} navigate={navigate} />; else if (route.name === 'cases') content = <CasesPage t={t} lang={lang} navigate={navigate} />; else if (route.name === 'approach') content = <ApproachPage t={t} lang={lang} navigate={navigate} />; else if (route.name === 'about') content = <AboutPage t={t} lang={lang} navigate={navigate} />; else if (route.name === 'contact') content = <ContactPage t={t} lang={lang} />; else if (route.name === 'privacy') content = <PrivacyPage t={t} />; else content = <NotFoundPage t={t} navigate={navigate} />; return <div className="site-shell"><Header t={t} lang={lang} setLang={setLang} navigate={navigate} route={route} />{content}<Footer t={t} navigate={navigate} /></div>; }

createRoot(document.getElementById('root')).render(<App />);
